def soln():
	s = input()
	temp = 0
	A = 0
	B = 0
	for i in range(0, 10):
		if i % 2 == 0 and s[i] == '1':
			A = A + 1
		if i % 2 == 1 and s[i] == '1':
			B = B + 1
		if A - B > 5 - (i + 1) // 2:
			print('TEAM-A', i + 1)
			break
		if B - A > 4 - i // 2:
			print('TEAM-B', i + 1)
			break
	if B == A:
		flag = 0
		for i in range(10, 20, 2):
			if s[i:i + 2] == '10':
				print('TEAM-A', i + 2)
				flag = 1
				break
			if s[i:i + 2] == '01':
				print('TEAM-B', i + 2)
				flag = 1
				break
		if flag == 0:
			print('TIE')
try:
	while True:
		soln()
except:
	pass
